#!/usr/bin/env node
// Stand-in for ESLint 9's CLI, so verify/js-tools.mjs runs offline. It does what PyIDE asks of the real one:
// `--version`, and `--format json --stdin --stdin-filename <file> [--fix-dry-run]` with the text on stdin. The flat
// config (eslint.config.mjs/js/cjs, found from the working folder up) is imported as ESLint does, and its rules
// `no-unused-vars` and `prefer-const` are checked on `let|const|var name =` declarations (prefer-const with its fix);
// unbalanced brackets are a fatal parsing error. A configuration that fails to load, or none, is ESLint's exit code 2
// with "Oops! Something went wrong! :(" on stderr. Each run is logged to node_modules/.standin-calls.log.
const fs = require('fs');
const path = require('path');
const { pathToFileURL } = require('url');

const VERSION = '9.0.0-standin';
const args = process.argv.slice(2);
try { fs.appendFileSync(path.join(__dirname, '..', '..', '.standin-calls.log'), `eslint ${args.join(' ')}\n`); } catch {}
if (args.includes('--version')) { process.stdout.write(`v${VERSION}\n`); process.exit(0); }
const at = args.indexOf('--stdin-filename');
const file = at >= 0 ? path.resolve(args[at + 1]) : path.resolve('<text>');
const fixDry = args.includes('--fix-dry-run');

const oops = (message) => {
  process.stderr.write(`\nOops! Something went wrong! :(\n\nESLint: ${VERSION}\n\n${message}\n`);
  process.exit(2);
};

function findConfig() {
  for (let d = process.cwd(); ; d = path.dirname(d)) {
    for (const f of ['eslint.config.js', 'eslint.config.mjs', 'eslint.config.cjs']) if (fs.existsSync(path.join(d, f))) return path.join(d, f);
    if (path.dirname(d) === d) return null;
  }
}

const SEVERITY = { off: 0, warn: 1, error: 2, 0: 0, 1: 1, 2: 2 };
function rulesOf(configs) {
  const rules = {};
  for (const c of [].concat(configs || [])) {
    for (const [name, v] of Object.entries(c?.rules || {})) rules[name] = SEVERITY[Array.isArray(v) ? v[0] : v] ?? 0;
  }
  return rules;
}

function position(text, offset) {
  const before = text.slice(0, offset).split('\n');
  return { line: before.length, column: before[before.length - 1].length + 1 };
}

function balanced(text) {
  const stack = [];
  let quote = null;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quote) { if (c === '\\') i++; else if (c === quote) quote = null; continue; }
    if (c === '"' || c === "'" || c === '`') { quote = c; continue; }
    if ('([{'.includes(c)) stack.push(c);
    else if (')]}'.includes(c)) { if ('([{'.indexOf(stack.pop()) !== ')]}'.indexOf(c)) return i; }
    else if (c === ';' && stack[stack.length - 1] === '(') return i;
  }
  return stack.length ? text.length : -1;
}

function lint(text, rules) {
  const bad = balanced(text);
  if (bad >= 0) return [{ ruleId: null, fatal: true, severity: 2, message: 'Parsing error: Unexpected token', ...position(text, bad), nodeType: null }];
  const messages = [];
  const decl = /\b(let|const|var)\s+([A-Za-z_$][\w$]*)\s*=(?!=)/g;
  for (let m; (m = decl.exec(text));) {
    const [, kind, name] = m;
    const nameAt = m.index + m[0].indexOf(name, kind.length);
    const esc = name.replace(/\$/g, '\\$');
    const uses = (text.match(new RegExp(`(?<![\\w$])${esc}(?![\\w$])`, 'g')) || []).length;
    const start = position(text, nameAt);
    const end = position(text, nameAt + name.length);
    const at = { line: start.line, column: start.column, endLine: end.line, endColumn: end.column };
    if (rules['no-unused-vars'] && uses === 1) {
      messages.push({ ruleId: 'no-unused-vars', severity: rules['no-unused-vars'], message: `'${name}' is assigned a value but never used.`, messageId: 'unusedVar', nodeType: 'Identifier', ...at });
    }
    const reassigned = new RegExp(`(?<![\\w$.])${esc}\\s*(?:[-+*/%]?=(?!=)|\\+\\+|--)`, 'g');
    const assignments = (text.match(reassigned) || []).length;
    if (rules['prefer-const'] && kind === 'let' && assignments <= 1) {
      messages.push({ ruleId: 'prefer-const', severity: rules['prefer-const'], message: `'${name}' is never reassigned. Use 'const' instead.`, messageId: 'useConst', nodeType: 'Identifier', ...at,
        fix: { range: [m.index, m.index + 3], text: 'const' } });
    }
  }
  // `// eslint-disable-next-line rule, rule` on the line above turns those rules off for the line.
  const lines = text.split(/\r?\n/);
  const disabled = (m) => {
    const d = /\/\/\s*eslint-disable-next-line\b(.*)$/.exec(lines[m.line - 2] || '');
    return d && (!d[1].trim() || d[1].split(',').map((s) => s.trim()).includes(m.ruleId));
  };
  return messages.filter((m) => !disabled(m)).sort((a, b) => a.line - b.line || a.column - b.column);
}

function applyFixes(text, messages) {
  let out = '';
  let last = 0;
  for (const m of messages.filter((x) => x.fix).sort((a, b) => a.fix.range[0] - b.fix.range[0])) {
    if (m.fix.range[0] < last) continue;
    out += text.slice(last, m.fix.range[0]) + m.fix.text;
    last = m.fix.range[1];
  }
  return out + text.slice(last);
}

let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (d) => (input += d));
process.stdin.on('end', async () => {
  const configFile = findConfig();
  if (!configFile) oops("ESLint couldn't find an eslint.config.(js|mjs|cjs) file.");
  let configs;
  try {
    configs = (await import(pathToFileURL(configFile).href)).default;
  } catch (err) {
    oops(`${err.name}: ${err.message}`);
  }
  const rules = rulesOf(configs);
  let messages = lint(input, rules);
  let output;
  if (fixDry && messages.some((m) => m.fix)) {
    output = applyFixes(input, messages);
    messages = lint(output, rules);
  }
  const count = (sev, fixable) => messages.filter((m) => m.severity === sev && (!fixable || m.fix)).length;
  const result = {
    filePath: file, messages, suppressedMessages: [],
    errorCount: count(2), fatalErrorCount: messages.filter((m) => m.fatal).length, warningCount: count(1),
    fixableErrorCount: count(2, true), fixableWarningCount: count(1, true),
    ...(output !== undefined ? { output } : messages.length ? { source: input } : {}), usedDeprecatedRules: [],
  };
  process.stdout.write(JSON.stringify([result]));
  process.exitCode = result.errorCount ? 1 : 0;
});
